import { useEffect, useRef } from "react";

/**
 * Variant E — "Swarm Intelligence"
 * Particles exhibit flocking behavior (alignment, cohesion, separation)
 * creating organic swarm patterns. They form loose groups that flow
 * and merge. Mouse scatters the swarm on approach. No trails.
 * Uses spatial grid for efficient neighbor lookups.
 */
export default function BgVariantE() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let W, H, dpr;
    let mouse = { x: -9999, y: -9999 };
    const COUNT = 1200;
    const MOUSE_RADIUS = 160;
    const NEIGHBOR_DIST = 60;
    const CELL_SIZE = 65;

    const COLORS = [
      [255, 114, 161],
      [180, 139, 255],
      [127, 211, 255],
      [120, 255, 168],
      [200, 210, 235],
      [200, 210, 235],
    ];

    let particles = [];
    let gridCols, gridRows;
    let grid;

    const initParticle = () => {
      const c = COLORS[Math.floor(Math.random() * COLORS.length)];
      const angle = Math.random() * Math.PI * 2;
      const speed = 0.3 + Math.random() * 0.5;
      return {
        x: Math.random() * (W || 1920),
        y: Math.random() * (H || 1080),
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        size: 0.5 + Math.random() * 1.2,
        r: c[0], g: c[1], b: c[2],
        alpha: 0.12 + Math.random() * 0.22,
      };
    };

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      gridCols = Math.ceil(W / CELL_SIZE) + 1;
      gridRows = Math.ceil(H / CELL_SIZE) + 1;
      particles = [];
      for (let i = 0; i < COUNT; i++) particles.push(initParticle());
    };
    resize();
    window.addEventListener("resize", resize);

    const onMove = (e) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    window.addEventListener("mousemove", onMove);

    let raf;
    const MAX_SPEED = 2.0;

    const draw = () => {
      ctx.clearRect(0, 0, W, H);

      // Build spatial grid
      grid = new Array(gridCols * gridRows);
      for (let i = 0; i < grid.length; i++) grid[i] = [];
      for (const p of particles) {
        const gc = Math.floor(p.x / CELL_SIZE);
        const gr = Math.floor(p.y / CELL_SIZE);
        if (gc >= 0 && gc < gridCols && gr >= 0 && gr < gridRows) {
          grid[gr * gridCols + gc].push(p);
        }
      }

      for (const p of particles) {
        // Find neighbors via grid
        const gc = Math.floor(p.x / CELL_SIZE);
        const gr = Math.floor(p.y / CELL_SIZE);
        let avgVx = 0, avgVy = 0, avgX = 0, avgY = 0;
        let sepX = 0, sepY = 0, count = 0;

        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            const nr = gr + dr, nc = gc + dc;
            if (nr < 0 || nr >= gridRows || nc < 0 || nc >= gridCols) continue;
            const cell = grid[nr * gridCols + nc];
            for (const q of cell) {
              if (q === p) continue;
              const dx = q.x - p.x;
              const dy = q.y - p.y;
              const d = Math.sqrt(dx * dx + dy * dy);
              if (d > NEIGHBOR_DIST) continue;

              count++;
              avgVx += q.vx;
              avgVy += q.vy;
              avgX += q.x;
              avgY += q.y;

              // Separation
              if (d < 20 && d > 0) {
                sepX -= (dx / d) * (1 - d / 20);
                sepY -= (dy / d) * (1 - d / 20);
              }
            }
          }
        }

        if (count > 0) {
          // Alignment
          avgVx /= count;
          avgVy /= count;
          p.vx += (avgVx - p.vx) * 0.03;
          p.vy += (avgVy - p.vy) * 0.03;

          // Cohesion
          avgX /= count;
          avgY /= count;
          p.vx += (avgX - p.x) * 0.0005;
          p.vy += (avgY - p.y) * 0.0005;

          // Separation
          p.vx += sepX * 0.15;
          p.vy += sepY * 0.15;
        }

        // Mouse scatter
        const mdx = p.x - mouse.x;
        const mdy = p.y - mouse.y;
        const mdist = Math.sqrt(mdx * mdx + mdy * mdy);
        if (mdist < MOUSE_RADIUS && mdist > 0) {
          const f = (1 - mdist / MOUSE_RADIUS) * 2.5;
          p.vx += (mdx / mdist) * f;
          p.vy += (mdy / mdist) * f;
        }

        // Clamp speed
        const speed = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
        if (speed > MAX_SPEED) {
          p.vx = (p.vx / speed) * MAX_SPEED;
          p.vy = (p.vy / speed) * MAX_SPEED;
        }

        p.x += p.vx;
        p.y += p.vy;

        // Wrap
        if (p.x < -10) p.x = W + 10;
        if (p.x > W + 10) p.x = -10;
        if (p.y < -10) p.y = H + 10;
        if (p.y > H + 10) p.y = -10;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${p.r},${p.g},${p.b},${p.alpha})`;
        ctx.fill();
      }

      raf = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", onMove);
    };
  }, []);

  return (
    <canvas ref={canvasRef}
      style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none" }} />
  );
}
