import React, { useState } from "react";
import BgVariantA from "../components/BgVariantA";
import BgVariantB from "../components/BgVariantB";
import BgVariantC from "../components/BgVariantC";
import BgVariantD from "../components/BgVariantD";
import BgVariantE from "../components/BgVariantE";
import BgVariantF from "../components/BgVariantF";
import "./Landing.css";

/* Reuse Landing's icons */
const IconGraph = () => (
  <svg viewBox="0 0 24 24" aria-hidden="true">
    <path d="M3 21V3" /><path d="M3 21h18" /><path d="M6 15l4-5 3 3 5-7" />
    <circle cx="6" cy="15" r="1.4" /><circle cx="10" cy="10" r="1.4" />
    <circle cx="13" cy="13" r="1.4" /><circle cx="18" cy="6" r="1.4" />
  </svg>
);
const IconLayers = () => (
  <svg viewBox="0 0 24 24" aria-hidden="true">
    <path d="M12 4l8 4-8 4-8-4 8-4z" /><path d="M4 12l8 4 8-4" /><path d="M4 16l8 4 8-4" />
  </svg>
);
const IconUser = () => (
  <svg viewBox="0 0 24 24" aria-hidden="true">
    <circle cx="12" cy="8" r="4" /><path d="M4 20c0-4 4-6 8-6s8 2 8 6" />
  </svg>
);
const IconDoc = () => (
  <svg viewBox="0 0 24 24" aria-hidden="true">
    <path d="M7 3h7l5 5v13a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z" />
    <path d="M14 3v5h5" /><path d="M9 13h6M9 17h6" />
  </svg>
);

const OPTIONS = [
  { id: "a", label: "Gravity Wells", desc: "Particles orbit invisible drifting gravity points — mouse adds a strong attractor" },
  { id: "b", label: "Rising Embers", desc: "Particles float upward with sine-wave drift — mouse creates an updraft that accelerates them" },
  { id: "c", label: "Depth Field", desc: "Multi-layer parallax — deeper particles are smaller/dimmer, mouse shifts layers at different rates" },
  { id: "d", label: "Magnetic Field", desc: "Particles flow along invisible field lines between poles — mouse acts as a movable pole" },
  { id: "e", label: "Swarm Intelligence", desc: "Flocking behavior (alignment, cohesion, separation) — mouse scatters the swarm" },
  { id: "f", label: "Waveform", desc: "Particles in oscillating wave rows with interference patterns — mouse distorts the waves locally" },
];

export default function BgDemo() {
  const [active, setActive] = useState("a");

  const renderBg = () => {
    switch (active) {
      case "a": return <BgVariantA />;
      case "b": return <BgVariantB />;
      case "c": return <BgVariantC />;
      case "d": return <BgVariantD />;
      case "e": return <BgVariantE />;
      case "f": return <BgVariantF />;
      default:  return <BgVariantA />;
    }
  };

  return (
    <div className="landing" style={{ height: "100vh" }}>
      {renderBg()}

      {/* Switcher panel */}
      <div style={{
        position: "fixed", top: 12, left: "50%", transform: "translateX(-50%)",
        zIndex: 1000, display: "flex", gap: 6, flexWrap: "wrap", justifyContent: "center",
        background: "rgba(11,13,18,0.85)", border: "1px solid rgba(255,255,255,0.12)",
        borderRadius: 12, padding: "8px 12px", backdropFilter: "blur(8px)",
        maxWidth: "90vw",
      }}>
        {OPTIONS.map(o => (
          <button
            key={o.id}
            onClick={() => setActive(o.id)}
            title={o.desc}
            style={{
              background: active === o.id ? "rgba(255,255,255,0.15)" : "transparent",
              border: active === o.id ? "1px solid rgba(255,255,255,0.3)" : "1px solid rgba(255,255,255,0.08)",
              color: active === o.id ? "#fff" : "#a9b2c7",
              borderRadius: 8,
              padding: "6px 12px",
              fontSize: 12,
              fontFamily: "Inter, system-ui, sans-serif",
              fontWeight: active === o.id ? 700 : 500,
              cursor: "pointer",
              transition: "all 0.2s ease",
              whiteSpace: "nowrap",
            }}
          >
            {o.label}
          </button>
        ))}
      </div>

      {/* Active option description */}
      <div style={{
        position: "fixed", bottom: 16, left: "50%", transform: "translateX(-50%)",
        zIndex: 1000, textAlign: "center",
        background: "rgba(11,13,18,0.85)", border: "1px solid rgba(255,255,255,0.12)",
        borderRadius: 10, padding: "8px 16px", backdropFilter: "blur(8px)",
        color: "#a9b2c7", fontSize: 13, fontFamily: "Inter, system-ui, sans-serif",
        maxWidth: "80vw",
      }}>
        <strong style={{ color: "#e8ebf4" }}>{OPTIONS.find(o => o.id === active)?.label}</strong>
        {" — "}{OPTIONS.find(o => o.id === active)?.desc}
        <br />
        <span style={{ fontSize: 11, opacity: 0.6 }}>Move your mouse around to see interactivity</span>
      </div>

      {/* Decorative circles */}
      <div className="magic-circle" aria-hidden="true" />
      <div className="magic-circle alt" aria-hidden="true" />
      <div className="magic-circle slow" aria-hidden="true" />

      {/* Landing content preview */}
      <div className="wrap" style={{ maxWidth: 1120, margin: "0 auto", padding: 40, position: "relative", zIndex: 3, display: "flex", flexDirection: "column", gap: 16, marginTop: 50 }}>
        <header className="hero">
          <h1 className="title">Hyder Mohyuddin</h1>
          <p className="subtitle">AI &amp; Software &bull; Systems &bull; Interfaces</p>
          <p className="mission">
            I build dependable AI tools and interfaces. At UChicago with <strong>Professor Jason Salavon</strong>, I absorbed responsibilities previously held across three <strong>CS M.S. teammates</strong> and got comfortable being handed unknowns. Recent work: real-time tensor devtools for <strong>Stable Diffusion/ComfyUI</strong> and a production <strong>SPIM research UI</strong>.
          </p>
        </header>

        <section className="grid" aria-label="Site sections">
          <div className="card card-1 portal">
            <span className="portal-glow portal-1" aria-hidden="true" />
            <div className="card-head"><span className="icon"><IconGraph /></span><h2>Skills</h2></div>
            <p className="card-copy">A visual and interactive map of my skills</p>
          </div>
          <div className="card card-2 portal">
            <span className="portal-glow portal-2" aria-hidden="true" />
            <div className="card-head"><span className="icon"><IconLayers /></span><h2>Projects</h2></div>
            <p className="card-copy">See my write-ups on past projects</p>
          </div>
          <div className="card card-3 portal">
            <span className="portal-glow portal-3" aria-hidden="true" />
            <div className="card-head"><span className="icon"><IconUser /></span><h2>About</h2></div>
            <p className="card-copy">Background, approach, and what I'm exploring</p>
          </div>
          <div className="card card-4 portal">
            <span className="portal-glow portal-4" aria-hidden="true" />
            <div className="card-head"><span className="icon"><IconDoc /></span><h2>Resume</h2></div>
            <p className="card-copy">Experience, education, and highlights</p>
          </div>
        </section>
      </div>
    </div>
  );
}
