import { useEffect, useRef } from "react";

/**
 * Variant A — "Gravity Wells"
 * Particles orbit invisible gravity points that slowly drift.
 * Mouse adds a strong attractor. Particles have varying sizes and
 * subtle accent colors. No trails — clean frame each tick.
 */
export default function BgVariantA() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let W, H, dpr;
    let mouse = { x: -9999, y: -9999 };
    const COUNT = 1400;
    const WELL_COUNT = 5;
    const MOUSE_RADIUS = 200;

    const COLORS = [
      [255, 114, 161],
      [180, 139, 255],
      [127, 211, 255],
      [120, 255, 168],
      [200, 210, 235],
      [200, 210, 235],
      [200, 210, 235],
    ];

    let particles = [];
    let wells = [];
    let time = 0;

    const initWell = () => ({
      x: Math.random() * (W || 1920),
      y: Math.random() * (H || 1080),
      vx: (Math.random() - 0.5) * 0.3,
      vy: (Math.random() - 0.5) * 0.3,
      mass: 40 + Math.random() * 60,
    });

    const initParticle = () => {
      const c = COLORS[Math.floor(Math.random() * COLORS.length)];
      return {
        x: Math.random() * (W || 1920),
        y: Math.random() * (H || 1080),
        vx: (Math.random() - 0.5) * 0.5,
        vy: (Math.random() - 0.5) * 0.5,
        size: 0.5 + Math.random() * 1.5,
        r: c[0], g: c[1], b: c[2],
        alpha: 0.1 + Math.random() * 0.3,
      };
    };

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      particles = [];
      wells = [];
      for (let i = 0; i < COUNT; i++) particles.push(initParticle());
      for (let i = 0; i < WELL_COUNT; i++) wells.push(initWell());
    };
    resize();
    window.addEventListener("resize", resize);

    const onMove = (e) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    window.addEventListener("mousemove", onMove);

    let raf;
    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      time += 0.016;

      // Drift wells
      for (const w of wells) {
        w.x += w.vx;
        w.y += w.vy;
        if (w.x < 0 || w.x > W) w.vx *= -1;
        if (w.y < 0 || w.y > H) w.vy *= -1;
        w.x = Math.max(0, Math.min(W, w.x));
        w.y = Math.max(0, Math.min(H, w.y));
      }

      for (const p of particles) {
        // Gravity from wells
        for (const w of wells) {
          const dx = w.x - p.x;
          const dy = w.y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy) + 50;
          const f = w.mass / (dist * dist) * 0.8;
          p.vx += (dx / dist) * f;
          p.vy += (dy / dist) * f;
        }

        // Mouse attractor
        const mdx = mouse.x - p.x;
        const mdy = mouse.y - p.y;
        const mdist = Math.sqrt(mdx * mdx + mdy * mdy);
        if (mdist < MOUSE_RADIUS && mdist > 5) {
          const mf = (1 - mdist / MOUSE_RADIUS) * 1.5;
          p.vx += (mdx / mdist) * mf;
          p.vy += (mdy / mdist) * mf;
        }

        p.vx *= 0.96;
        p.vy *= 0.96;
        p.x += p.vx;
        p.y += p.vy;

        // Wrap
        if (p.x < -20) p.x = W + 20;
        if (p.x > W + 20) p.x = -20;
        if (p.y < -20) p.y = H + 20;
        if (p.y > H + 20) p.y = -20;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${p.r},${p.g},${p.b},${p.alpha})`;
        ctx.fill();
      }

      raf = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", onMove);
    };
  }, []);

  return (
    <canvas ref={canvasRef}
      style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none" }} />
  );
}
