import { useEffect, useRef } from "react";

/**
 * Variant D — "Magnetic Field"
 * Particles align along invisible field lines emanating from 2-3 poles.
 * They flow along the field direction (like iron filings on a magnet).
 * Mouse acts as a movable pole that reshapes the field. No trails.
 */
export default function BgVariantD() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let W, H, dpr;
    let mouse = { x: -9999, y: -9999 };
    const COUNT = 1800;

    const COLORS = [
      [255, 114, 161],
      [180, 139, 255],
      [127, 211, 255],
      [120, 255, 168],
      [200, 210, 235],
      [200, 210, 235],
    ];

    // Fixed magnetic poles
    let poles = [];
    let particles = [];

    const initPoles = () => {
      poles = [
        { x: W * 0.25, y: H * 0.35, charge: 1 },
        { x: W * 0.75, y: H * 0.65, charge: -1 },
        { x: W * 0.5, y: H * 0.15, charge: 0.6 },
      ];
    };

    const initParticle = () => {
      const c = COLORS[Math.floor(Math.random() * COLORS.length)];
      return {
        x: Math.random() * (W || 1920),
        y: Math.random() * (H || 1080),
        vx: 0,
        vy: 0,
        size: 0.4 + Math.random() * 1.2,
        r: c[0], g: c[1], b: c[2],
        alpha: 0.1 + Math.random() * 0.25,
        life: 0,
        maxLife: 300 + Math.random() * 400,
      };
    };

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      initPoles();
      particles = [];
      for (let i = 0; i < COUNT; i++) particles.push(initParticle());
    };
    resize();
    window.addEventListener("resize", resize);

    const onMove = (e) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    window.addEventListener("mousemove", onMove);

    let raf;

    // Compute field direction at a point
    const fieldAt = (px, py) => {
      let fx = 0, fy = 0;

      for (const pole of poles) {
        const dx = px - pole.x;
        const dy = py - pole.y;
        const dist = Math.sqrt(dx * dx + dy * dy) + 80;
        const strength = (pole.charge * 120) / (dist * dist);
        fx += (dx / dist) * strength;
        fy += (dy / dist) * strength;
      }

      // Mouse as a strong pole
      if (mouse.x > -9000) {
        const dx = px - mouse.x;
        const dy = py - mouse.y;
        const dist = Math.sqrt(dx * dx + dy * dy) + 40;
        const strength = 200 / (dist * dist);
        fx += (dx / dist) * strength;
        fy += (dy / dist) * strength;
      }

      return { fx, fy };
    };

    const draw = () => {
      ctx.clearRect(0, 0, W, H);

      for (const p of particles) {
        const { fx, fy } = fieldAt(p.x, p.y);

        // Align velocity along field lines
        const fLen = Math.sqrt(fx * fx + fy * fy) + 0.001;
        const speed = Math.min(fLen * 800, 2.5);
        p.vx += (fx / fLen) * speed * 0.06;
        p.vy += (fy / fLen) * speed * 0.06;

        p.vx *= 0.94;
        p.vy *= 0.94;
        p.x += p.vx;
        p.y += p.vy;
        p.life++;

        // Respawn when expired or out of bounds
        if (p.life > p.maxLife || p.x < -50 || p.x > W + 50 || p.y < -50 || p.y > H + 50) {
          p.x = Math.random() * W;
          p.y = Math.random() * H;
          p.vx = 0;
          p.vy = 0;
          p.life = 0;
        }

        // Fade in/out
        const fadeIn = Math.min(1, p.life / 40);
        const fadeOut = Math.min(1, (p.maxLife - p.life) / 60);
        const a = p.alpha * fadeIn * fadeOut;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${p.r},${p.g},${p.b},${a})`;
        ctx.fill();
      }

      raf = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", onMove);
    };
  }, []);

  return (
    <canvas ref={canvasRef}
      style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none" }} />
  );
}
