import { useEffect, useRef } from "react";

/**
 * Variant C — "Depth Field"
 * Particles exist on multiple depth layers (parallax). Deeper particles
 * are smaller, dimmer, slower. Mouse shifts layers at different rates,
 * creating a 3D parallax feel. Particles drift slowly sideways. No trails.
 */
export default function BgVariantC() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let W, H, dpr;
    let mouse = { x: 0, y: 0 };
    let smoothMouse = { x: 0, y: 0 };
    const COUNT = 2000;

    const COLORS = [
      [255, 114, 161],
      [180, 139, 255],
      [127, 211, 255],
      [120, 255, 168],
      [200, 210, 235],
      [200, 210, 235],
      [200, 210, 235],
    ];

    let particles = [];

    const initParticle = () => {
      const c = COLORS[Math.floor(Math.random() * COLORS.length)];
      const depth = Math.random(); // 0 = far, 1 = near
      return {
        x: Math.random() * (W || 1920),
        y: Math.random() * (H || 1080),
        vx: (Math.random() - 0.5) * 0.15,
        vy: (Math.random() - 0.5) * 0.08,
        depth,
        size: 0.3 + depth * 1.8,
        r: c[0], g: c[1], b: c[2],
        alpha: (0.04 + depth * 0.25),
        parallaxScale: 0.02 + depth * 0.06,
        pulse: Math.random() * Math.PI * 2,
        pulseSpeed: 0.3 + Math.random() * 0.8,
      };
    };

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      mouse.x = W / 2;
      mouse.y = H / 2;
      smoothMouse.x = W / 2;
      smoothMouse.y = H / 2;
      particles = [];
      for (let i = 0; i < COUNT; i++) particles.push(initParticle());
      // Sort by depth so far particles draw first
      particles.sort((a, b) => a.depth - b.depth);
    };
    resize();
    window.addEventListener("resize", resize);

    const onMove = (e) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    window.addEventListener("mousemove", onMove);

    let raf;
    let time = 0;

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      time += 0.016;

      // Smooth mouse for parallax
      smoothMouse.x += (mouse.x - smoothMouse.x) * 0.05;
      smoothMouse.y += (mouse.y - smoothMouse.y) * 0.05;
      const offsetX = (smoothMouse.x - W / 2);
      const offsetY = (smoothMouse.y - H / 2);

      for (const p of particles) {
        // Slow drift
        p.x += p.vx;
        p.y += p.vy;

        // Wrap
        if (p.x < -20) p.x = W + 20;
        if (p.x > W + 20) p.x = -20;
        if (p.y < -20) p.y = H + 20;
        if (p.y > H + 20) p.y = -20;

        // Parallax offset
        const px = p.x + offsetX * p.parallaxScale;
        const py = p.y + offsetY * p.parallaxScale;

        // Subtle pulse
        p.pulse += p.pulseSpeed * 0.016;
        const pulseAlpha = 0.7 + 0.3 * Math.sin(p.pulse);
        const a = p.alpha * pulseAlpha;

        ctx.beginPath();
        ctx.arc(px, py, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${p.r},${p.g},${p.b},${a})`;
        ctx.fill();
      }

      raf = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", onMove);
    };
  }, []);

  return (
    <canvas ref={canvasRef}
      style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none" }} />
  );
}
