import { useEffect, useRef } from "react";

/**
 * Variant F — "Waveform"
 * Particles are arranged in horizontal wave rows that oscillate
 * with different phases/amplitudes, creating an interference pattern.
 * Mouse distorts the waves locally (like poking a calm surface).
 * Particles subtly shift color based on displacement. No trails.
 */
export default function BgVariantF() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let W, H, dpr;
    let mouse = { x: -9999, y: -9999 };
    const SPACING_X = 8;
    const SPACING_Y = 18;
    const MOUSE_RADIUS = 180;

    const ACCENT = [
      [255, 114, 161],
      [180, 139, 255],
      [127, 211, 255],
      [120, 255, 168],
    ];

    let cols, rows;
    let time = 0;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cols = Math.ceil(W / SPACING_X) + 2;
      rows = Math.ceil(H / SPACING_Y) + 2;
    };
    resize();
    window.addEventListener("resize", resize);

    const onMove = (e) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    window.addEventListener("mousemove", onMove);

    let raf;

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      time += 0.012;

      for (let r = 0; r < rows; r++) {
        const baseY = r * SPACING_Y;
        const rowPhase = r * 0.4;
        const rowAmp = 4 + Math.sin(r * 0.15 + time * 0.3) * 3;
        const ci = r % 4;
        const [cr, cg, cb] = ACCENT[ci];

        for (let c = 0; c < cols; c++) {
          const baseX = c * SPACING_X;

          // Multi-frequency wave
          let dy = 0;
          dy += Math.sin(baseX * 0.015 + time * 1.2 + rowPhase) * rowAmp;
          dy += Math.sin(baseX * 0.008 - time * 0.7 + rowPhase * 0.5) * rowAmp * 0.6;
          dy += Math.sin(baseX * 0.025 + time * 2.0 + r * 0.2) * 1.5;

          // Mouse distortion
          const mdx = baseX - mouse.x;
          const mdy = (baseY + dy) - mouse.y;
          const mdist = Math.sqrt(mdx * mdx + mdy * mdy);
          let mouseDisp = 0;
          if (mdist < MOUSE_RADIUS) {
            const f = (1 - mdist / MOUSE_RADIUS);
            mouseDisp = f * f * 35;
            // Push away from cursor
            dy += (mdy / (mdist || 1)) * mouseDisp;
          }

          const fx = baseX;
          const fy = baseY + dy;

          // Displacement magnitude affects alpha and color blend
          const disp = Math.abs(dy) / (rowAmp * 2 + 10);
          const alpha = 0.06 + disp * 0.12 + (mdist < MOUSE_RADIUS ? (1 - mdist / MOUSE_RADIUS) * 0.15 : 0);
          const size = 0.6 + disp * 0.8;

          // Blend toward accent when displaced
          const blend = Math.min(1, disp * 1.5);
          const fr = Math.round(200 + (cr - 200) * blend);
          const fg = Math.round(210 + (cg - 210) * blend);
          const fb = Math.round(235 + (cb - 235) * blend);

          ctx.beginPath();
          ctx.arc(fx, fy, size, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${fr},${fg},${fb},${alpha})`;
          ctx.fill();
        }
      }

      raf = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", onMove);
    };
  }, []);

  return (
    <canvas ref={canvasRef}
      style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none" }} />
  );
}
